<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import Errors from '../Components/Errors.vue';
const props = defineProps<{register: boolean}>();
const form = useForm({name:'',email:'',password:'',password_confirmation:'',remember:false});
function submit() { form.post(props.register ? '/register' : '/login', {onFinish:()=>form.reset('password','password_confirmation')}); }
</script>
<template><div class="auth-page"><Head :title="register ? 'Create account' : 'Sign in'"/><section class="auth-story"><div class="brand light"><span class="brand-mark">s<span>t</span></span>SpendTrace</div><div><p class="eyebrow">LESS TYPING. MORE CLARITY.</p><h1>A little receipt.<br>A clearer picture.</h1><p>Capture the everyday. Keep your originals.<br>Know what you spent, without the guesswork.</p></div><small>YOUR SPENDING. YOUR PAPER TRAIL.</small></section><section class="auth-form"><p class="eyebrow">WELCOME TO SPENDTRACE</p><h2>{{ register ? 'Start your paper trail.' : 'Good to see you.' }}</h2><p class="muted">{{ register ? 'One account. Your own private ledger.' : 'Sign in to your spending ledger.' }}</p><form @submit.prevent="submit"><Errors :errors="form.errors"/><label v-if="register">Name<input v-model="form.name" autocomplete="name" required maxlength="100"/></label><label>Email<input v-model="form.email" type="email" autocomplete="email" required/></label><label>Password<input v-model="form.password" type="password" :autocomplete="register ? 'new-password' : 'current-password'" required :minlength="register ? 12 : undefined"/></label><label v-if="register">Confirm password<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required/></label><small v-if="register" class="muted">Use at least 12 characters.</small><label v-else class="check"><input v-model="form.remember" type="checkbox"/>Keep me signed in</label><button class="button primary full" :disabled="form.processing">{{ form.processing ? 'Please wait…' : register ? 'Create account' : 'Sign in' }} <span>→</span></button></form><p class="auth-switch">{{ register ? 'Already have an account?' : 'New here?' }} <Link :href="register ? '/login' : '/register'">{{ register ? 'Sign in' : 'Create an account' }}</Link></p></section></div></template>
